example_solution:
package secrethandshake

var signals = []string{"wink", "double blink", "close your eyes", "jump"}

// Handshake returns sequence to perform corresponding to the given code.
func Handshake(code uint) (h []string) {
	switch {
	case code < 1:
	case code&16 == 0:
		for _, s := range signals {
			if code&1 != 0 {
				h = append(h, s)
			}
			code >>= 1
		}
	default:
		for i := 3; i >= 0; i-- {
			if code&8 != 0 {
				h = append(h, signals[i])
			}
			code <<= 1
		}
	}
	return h
}

test_code:
package secrethandshake

import (
	"slices"
	"testing"
)

func TestHandshake(t *testing.T) {
	for _, tc := range tests {
		t.Run(tc.description, func(t *testing.T) {
			actual := Handshake(tc.input)
			// use len() to allow either nil or empty list, because they are not equal by DeepEqual
			if len(actual) == 0 && len(tc.expected) == 0 {
				return
			}
			if !slices.Equal(actual, tc.expected) {
				t.Fatalf("Handshake(%d) = %q, want: %q", tc.input, actual, tc.expected)
			}
		})
	}
}

func BenchmarkHandshake(b *testing.B) {
	for range b.N {
		for j := uint(0); j < 32; j++ {
			Handshake(j)
		}
	}
}
